(()=>{const data=JSON.parse(document.getElementById('setu-injection-data').textContent),drug=document.getElementById('inj-analyte'),metric=document.getElementById('inj-metric');function draw(){const k=+metric.value,sets=[data[drug.value+'1'],data[drug.value+'2']],values=sets.flat().map(r=>r[k]),lo=Math.min(...values),hi=Math.max(...values),pad=Math.max((hi-lo)*.15,k===3?1:.01),min=lo-pad,max=hi+pad,x=n=>70+(n-1)/79*940,y=v=>285-(v-min)/(max-min)*235;let svg='<svg viewBox="0 0 1050 340" role="img" aria-label="'+drug.options[drug.selectedIndex].text+' '+metric.options[metric.selectedIndex].text+' across 80 sample injections in both sequences">';for(let j=0;j<=4;j++){const v=min+(max-min)*j/4;svg+='<path d="M70 '+y(v)+'H1010" stroke="#dce5eb"/><text x="60" y="'+(y(v)+4)+'" text-anchor="end" fill="#526675" font-size="12">'+v.toFixed(k===3?1:3)+'</text>';}[1,10,20,30,40,50,60,70,80].forEach(n=>svg+='<text x="'+x(n)+'" y="308" text-anchor="middle" fill="#526675" font-size="12">'+n+'</text>');sets.forEach((rows,j)=>{const color=j?'#f58220':'#0b3b60',name=j?'Sequence 2 (recycled)':'Sequence 1 (virgin)';svg+='<polyline fill="none" stroke="'+color+'" stroke-width="2" '+(j?'stroke-dasharray="6 3"':'')+' points="'+rows.map(r=>x(r[0])+','+y(r[k])).join(' ')+'"/>';rows.forEach(r=>{const tip=name+' · sample '+r[0]+' · source vial '+r[1]+' · '+metric.options[metric.selectedIndex].text+': '+r[k];svg+='<circle tabindex="0" aria-label="'+tip+'" cx="'+x(r[0])+'" cy="'+y(r[k])+'" r="3.5" fill="'+color+'"><title>'+tip+'</title></circle>';});});svg+='<text x="540" y="334" text-anchor="middle" font-size="13" fill="#0b3b60">Sample injection number (1–80)</text></svg>';document.getElementById('injection-chart').innerHTML=svg;}drug.addEventListener('change',draw);metric.addEventListener('change',draw);draw();})();